use atty::{self, Stream};

use clap::ArgMatches;

#[cfg(windows)]
use ansi_term;

use crate::assets::HighlightingAssets;
use crate::clap_app::CliRuntime;
use crate::errors::*;

pub use crate::clap_app::{Config, OutputComponent, OutputComponents, OutputWrap, PagingMode};

pub struct App {
    pub matches: ArgMatches<'static>,
    interactive_output: bool,
}

impl App {
    pub fn new() -> Result<Self> {
        #[cfg(windows)]
        let _ = ansi_term::enable_ansi_support();

        let interactive_output = atty::is(Stream::Stdout);
        let mut runtime = CliRuntime::new(interactive_output);

        Ok(App {
            matches: runtime.collect_and_parse()?,
            interactive_output,
        })
    }

    pub fn config(&self) -> Result<Config> {
        let mut runtime = CliRuntime::new(self.interactive_output);
        runtime.build_config(&self.matches)
    }

    pub fn highlighting_assets() -> HighlightingAssets {
        HighlightingAssets::new()
    }

    pub fn config_file_path() -> String {
        CliRuntime::new(false).config_file_display()
    }

    pub fn config_directory() -> String {
        CliRuntime::new(false).config_directory_display()
    }

    pub fn cache_directory() -> String {
        CliRuntime::new(false).cache_directory_display()
    }

    pub fn run_cache_subcommand(matches: &ArgMatches) -> Result<()> {
        CliRuntime::new(false).run_cache_subcommand(matches)
    }

    pub fn list_languages(config: &Config) -> Result<()> {
        CliRuntime::new(config.colored_output).list_languages(config)
    }
}

